mapper.select:
SELECT id,user_id,screen_num,tenant_id,industry_code,app_ver_code,creator,modifier,is_watermark, watermark_content_type,watermark_density,watermark_font_size,watermark_transparency, IFNULL(video_amplification, 1) AS "videoAmplification", IFNULL(video_assembly_amplification, 1) AS "videoAssemblyAmplification" , IFNULL(automatic_enlarged_images, 1) AS "automaticEnlargedImages",video_init_url,video_loading,video_preloader,video_preloader_num,video_preloader_model FROM vm_video_screen_config WHERE delete_flag = 0
AND user_id= #{userId}
AND tenant_id= #{tenantId}
AND industry_code= #{industryCode}
AND tenant_id IS NULL AND industry_code IS NULL
ORDER BY create_time DESC

SELECT id,user_id,screen_num,tenant_id,industry_code,app_ver_code,creator,modifier,is_watermark,
watermark_content_type,watermark_density,watermark_font_size,watermark_transparency,
IFNULL(video_amplification, 1) AS "videoAmplification", IFNULL(video_assembly_amplification, 1) AS "videoAssemblyAmplification"
, IFNULL(automatic_enlarged_images, 1) AS "automaticEnlargedImages"
FROM vm_video_screen_config
WHERE delete_flag = 0
    AND user_id= #{userId}
    AND tenant_id= #{tenantId}
    AND industry_code= #{industryCode}
ORDER BY create_time DESC LIMIT 1

mapper.update:
update vm_video_screen_config
set screen_num             = #{screenNum},
    modifier               = #{modifier},
    update_time            = #{updateTime},
    is_watermark           = #{isWatermark},
    watermark_content_type = #{watermarkContentType},
    watermark_density      = #{watermarkDensity},
    watermark_font_size    = #{watermarkFontSize},
    watermark_transparency = #{watermarkTransparency},
    video_init_url         = #{videoInitUrl},
    video_preloader = #{videoPreloader}

        ,video_amplification = #{videoAmplification}


        ,video_assembly_amplification = #{videoAssemblyAmplification}


       ,automatic_enlarged_images = #{automaticEnlargedImages}


        ,video_loading = #{videoLoading}

    ,video_preloader_num = #{videoPreloaderNum}
    ,video_preloader_model = #{videoPreloaderModel}
where id = #{id}

update vm_video_screen_config
set
    modifier = #{modifier},
    update_time = #{updateTime},
    video_init_url = #{videoInitUrl}
where tenant_id = #{tenantId}
AND industry_code = #{industryCode}
